create schema app;
create table app.parent ("p.id" int primary key, "p.name" text unique);
create table app.t (
  id int,
  "a.b" int not null default 1,
  "c.d" text collate "C",
  "e.f" int generated always as ("a.b" * 2) stored,
  "g.h" int,
  "i.d" int generated by default as identity,
  "s.n" serial,
  constraint "t.pk" primary key (id, "a.b"),
  constraint "t.chk" check ("a.b" > 0),
  constraint "t.uq" unique ("c.d"),
  constraint "t.fk" foreign key ("g.h") references app.parent ("p.id") on delete set null ("g.h")
);
create index "t.idx" on app.t ("c.d", "a.b" desc) include ("g.h");
comment on column app.t."a.b" is 'dotted';
comment on constraint "t.chk" on app.t is 'chk';
comment on constraint "t.fk" on app.t is 'fk';
comment on index app."t.idx" is 'idx';
create statistics app."t.stat" on "a.b", "c.d" from app.t;
create function app.trg() returns trigger language plpgsql as $$ begin return new; end $$;
create trigger "t.trg" before update of "a.b" on app.t for each row execute function app.trg();
comment on trigger "t.trg" on app.t is 'trg';
alter table app.t enable row level security;
create policy "t.pol" on app.t using ("a.b" > 0);
comment on policy "t.pol" on app.t is 'pol';
create rule "t.rule" as on delete to app.t do also nothing;
alter table app.t cluster on "t.idx";
grant select ("a.b") on app.t to public;
create view app.vw as select "a.b" from app.t;
comment on column app.vw."a.b" is 'view col';
create table app.xy ("k.v" int primary key, note text);
create index "x.y.note" on app.xy (note);
create sequence app.sq owned by app.xy."k.v";
create type app.typ as ("at.tr" int, b text);
comment on column app.typ."at.tr" is 'attr';
create type app.enm as enum ('x.y', 'z');
create domain app.dom as int constraint "do.chk" check (value > 0);
create table app.pt ("r.k" int not null, v text) partition by range ("r.k");
create table app.pt1 partition of app.pt for values from (0) to (10);
create table app.tr_src (id int primary key, "u.k" int not null);
create unique index "tr.ri" on app.tr_src ("u.k");
alter table app.tr_src replica identity using index "tr.ri";
create function app.stmt_trg() returns trigger language plpgsql as $$ begin return null; end $$;
create trigger "tt.trg" after update on app.tr_src referencing old table as "old.rows" new table as "new.rows" for each statement execute function app.stmt_trg();
create publication "pub.dot" for table app.tr_src ("u.k", id);
